#define _GNU_SOURCE
#include <dlfcn.h>
#include <linux/kvm.h>
#include <stdarg.h>
#include <stdatomic.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <sys/ioctl.h>
#include <sys/mman.h>

static _Atomic(struct kvm_run *) runs[65536];
static _Atomic unsigned char vcpus[65536];
static _Atomic uint64_t mmio[1 << 20];
static _Atomic uint64_t ports[65536];
static _Atomic uint64_t reasons[128];
static int (*real_ioctl)(int, unsigned long, ...);
static void *(*real_mmap)(void *, size_t, int, int, int, off_t);

__attribute__((constructor)) static void init(void) {
    real_ioctl = dlsym(RTLD_NEXT, "ioctl");
    real_mmap = dlsym(RTLD_NEXT, "mmap");
}

int ioctl(int fd, unsigned long request, ...) {
    va_list args;
    va_start(args, request);
    unsigned long arg = va_arg(args, unsigned long);
    va_end(args);
    int result = real_ioctl(fd, request, arg);
    if (request == KVM_CREATE_VCPU && result >= 0 && result < 65536)
        vcpus[result] = 1;
    if (request == KVM_RUN && result == 0 && fd >= 0 && fd < 65536) {
        struct kvm_run *run = runs[fd];
        if (run) {
            if (run->exit_reason < 128)
                reasons[run->exit_reason]++;
            if (run->exit_reason == KVM_EXIT_MMIO && (run->mmio.phys_addr >> 12) < (1 << 20))
                mmio[run->mmio.phys_addr >> 12]++;
            if (run->exit_reason == KVM_EXIT_IO)
                ports[run->io.port]++;
        }
    }
    return result;
}

void *mmap(void *address, size_t size, int prot, int flags, int fd, off_t offset) {
    void *result = real_mmap(address, size, prot, flags, fd, offset);
    if (fd >= 0 && fd < 65536 && vcpus[fd] && offset == 0 && result != MAP_FAILED)
        runs[fd] = result;
    return result;
}

void *mmap64(void *address, size_t size, int prot, int flags, int fd, off64_t offset) {
    return mmap(address, size, prot, flags, fd, offset);
}

__attribute__((destructor)) static void finish(void) {
    uint64_t total = 0;
    for (int i = 0; i < 128; i++) total += reasons[i];
    if (!total) return;
    const char *path = getenv("PERF4_EXITS");
    if (!path) return;
    FILE *output = fopen(path, "w");
    if (!output) return;
    fprintf(output, "type,address,count\n");
    for (int i = 0; i < 128; i++)
        if (reasons[i]) fprintf(output, "exit,%d,%lu\n", i, (unsigned long)reasons[i]);
    for (int i = 0; i < (1 << 20); i++)
        if (mmio[i]) fprintf(output, "mmio,0x%lx,%lu\n", (unsigned long)i << 12, (unsigned long)mmio[i]);
    for (int i = 0; i < 65536; i++)
        if (ports[i]) fprintf(output, "io,0x%x,%lu\n", i, (unsigned long)ports[i]);
    fclose(output);
}
